EPS1 = [
dict(id="rom", n="罗马书", ab="罗", en="Romans", g="major", ic="⚖️", ch=16,
 au="使徒保罗（{{罗1:1}}），由德丢代笔（{{罗16:22}}）", date="约主后 56–57 年冬", place="哥林多（第三次旅行在希腊住三个月，{{徒20:2-3}}）",
 to="罗马城的教会（犹太与外邦信徒混合，多为家庭教会）", fr="corinth", dest="rome", acts="徒20:2-3；徒28",
 kw="义", core="神的义在福音上显明：本于信、以致于信；神在基督里称不敬虔的人为义，并使他们成圣、得荣，成就向亚伯拉罕的应许。",
 kv="罗1:16-17", mn="罪·义·圣·选·事（1–3 罪 / 3–5 义 / 6–8 圣 / 9–11 选 / 12–16 事）",
 bg="主后 49 年左右，革老丢皇帝将犹太人逐出罗马（{{徒18:2}}），外邦信徒一度成为罗马教会主体；54 年尼禄继位后犹太信徒陆续回城，饮食、节期之争随之而来（14–15 章）。保罗结束爱琴海周围的宣教，要把外邦教会的捐项送到耶路撒冷，再经罗马往西班牙（{{罗15:24-28}}）。他从未到过罗马，便先写这封最有系统的福音书信，作自我介绍、合一劝勉与宣教基地的预备。",
 cul="罗马是帝国首都，人口约百万，奴隶与被释奴占很大比例；犹太会堂十多所。帝国意识形态宣扬“凯撒的福音”与“罗马和平”，保罗却宣告真正的“福音”与“神的义”。荣辱文化、恩主—受惠关系、“强者/弱者”的社会分层，是 14–15 章的背景。",
 why=["保罗计划经罗马往西班牙宣教（15:24）", "罗马教会犹太与外邦信徒张力（14–15 章）", "有人毁谤保罗“作恶以成善”（3:8）", "系统陈明“因信称义”的福音以建立合一的宣教教会"],
 ol=[("1:1-17","引言：福音与神的义",1),("1:18-3:20","全人类都在罪下（外邦人、犹太人）",2.5),("3:21-5:21","因信称义：基督的挽回祭；亚伯拉罕；两个亚当",2.5),("6–8","成圣与圣灵中的生命：与基督联合，不被定罪",3),("9–11","神的信实与以色列：拣选、硬心、全家得救",3),("12–16","因神的慈悲献上活祭：教会、国家、强弱、宣教",4)],
 bt="罗马书是保罗对“整本圣经故事”的总纲：创造与审判（1 章，回应诗篇与智慧书）、亚当的堕落与基督的顺服（5 章）、亚伯拉罕之约（4 章）、西奈律法的功用（7 章）、先知应许的新心与圣灵（8 章，对照 {{结36:26-27}}）、以色列的余民与列国的归入（9–11 章，引用何西阿、以赛亚）、末后受造之物得赎（{{罗8:21}}）。全书引用旧约约 60 次，证明福音是“神从前藉众先知在圣经上所应许的”（{{罗1:2}}）。",
 ct="**两个约的元首**：亚当与基督是两位代表性元首（{{罗5:19}}），一人的悖逆使众人成为罪人，一人的顺服使众人成为义。==亚伯拉罕因信称义发生在受割礼之前；割礼是“因信称义的印证”==（{{罗4:11}}），这是改革宗把洗礼看作恩典之约的记号和印证、并给信徒儿女施洗的经文根据之一。9–11 章显明恩典之约里有“肉身的以色列”与“应许的儿女”之分（{{罗9:6-8}}），而橄榄树只有一棵：外邦人被接上，同属一个立约百姓。",
 key=["**唯独信心**：称义是法庭宣告，基于基督的义归算，不基于人里面的义（3:21–4:25）","**与基督联合**是成圣的根基：受洗归入他的死（6:3-4）","**圣灵的确据**：没有定罪（8:1），万事互相效力（8:28），金链（8:29-30）","**神的主权拣选**与神的信实（9–11 章）","**活祭的敬拜**与爱的律法（12–13 章）"],
 hard=[("!!罗马书 7:14-25 的“我”是谁？!!","奥古斯丁晚期、加尔文与多数改革宗释经家认为是重生的保罗：他“喜欢神的律”（7:22），却仍与残余的罪争战；这正合 HC 114“即使最圣洁的人也只是刚刚开始学着顺服”。另有学者认为是未重生者或以色列在律法下的经历。要点：律法本身是圣洁的，问题在罪；出路在“感谢神，靠着我们的主耶稣基督”（7:25）。"),
  ("!!罗马书 9 章：拣选是关乎个人得救，还是关乎民族使命?!!","保罗回答的问题是“这不是说神的话落了空”（9:6），答案是神按拣选的旨意在以色列中保留应许的儿女；“窑匠与泥”（9:21）关乎怜悯与刚硬，是得救论层面的。多特信经第一项教义正以此为根据；同时保罗以哀伤与传福音的热心（9:1-3；10:1）回应这教义，绝不是宿命论。"),
  ("!!“以色列全家都要得救”（11:26）!!","改革宗内部有三说：①全体选民（犹太与外邦，加尔文）；②犹太民族中全部选民逐代得救；③末期以色列民族大规模归信（不少清教徒与普林斯顿神学家持此）。共同点：都藉着信基督，不是另一条救法。")],
 conf=[("hc",60),("bc",22,"所以，我们当用保罗的话说：“人称义是因着信，不在乎遵行律法。”（罗3:28）然而，严格地说，这不是指信心本身使我们称义，因为信心只是一个工具，藉着它，我们得以接受基督为我们的义。"),("bc",15,"我们相信由于亚当的悖逆，原罪已传遍全人类。"),("dort",1,7,"拣选是神不变的旨意。"),("bc",36,"为了这个目的，神也赐权柄给政府，刑罚作恶的，保护行善的（罗13:4）。")],
 app=["每天以 8:1 开始：不被定罪的身份先于努力。","把教义变成敬拜：11:33-36 的颂赞是 1–11 章的终点。","在教会中按 14–15 章彼此接纳，不在非本质的事上论断弟兄。","把宣教放进预算与祷告（15:20-24）。"],
 ang={"历史":"写给尚未谋面、族群混合的首都教会","文学":"书信中夹有“驳论体”（diatribe）问答：“这样，怎么说呢？”","神学":"称义、成圣、拣选的系统论述","牧养":"合一与宣教的动员信"}),

dict(id="1co", n="哥林多前书", ab="林前", en="1 Corinthians", g="major", ic="🏛️", ch=16,
 au="使徒保罗与所提尼（{{林前1:1}}）", date="约主后 54–55 年春（五旬节前，{{林前16:8}}）", place="以弗所（第三次旅行）",
 to="哥林多教会（保罗第二次旅行时建立，{{徒18:1-11}}）", fr="ephesus", dest="corinth", acts="徒18:1-18；徒19",
 kw="纠正", core="被钉十字架的基督是神的能力与智慧；圣洁、合一、爱与复活的盼望，要改造一个被城市文化渗透的教会。",
 kv="林前2:2", mn="分党·淫乱·诉讼·婚姻·祭偶像·聚会·恩赐·复活（八问一答：十字架）",
 bg="哥林多于前 146 年被罗马毁灭，前 44 年由凯撒重建为罗马殖民地，是亚该亚省会，扼两海之间的地峡，商旅、水手、被释奴云集。保罗在此住了一年零六个月（{{徒18:11}}）。离开后，革来氏家里的人报告分党（{{林前1:11}}），教会又来信问婚姻、祭偶像之物、属灵恩赐等（{{林前7:1}}）。保罗在以弗所逐一回答。",
 cul="**罗马殖民地 + 希腊城邦**：讲究演说术与哲学（智慧），追捧名嘴；地峡运动会（每两年一次）是 9:24-27 赛跑比喻的背景；神庙林立（亚波罗、阿芙洛狄忒、医神庙），祭肉在市场出售（10:25）；私人宴会的阶层分座是主餐滥用（11:17-34）的背景。",
 why=["革来氏家报告：分党与骄傲（1:11）","风闻淫乱与姑息（5:1）","教会来信六问（7:1 起，“论到……”）","有人否认身体复活（15:12）"],
 ol=[("1–4","分党与十字架的智慧；仆人职分",4),("5–6","教会纪律、诉讼、身体是圣灵的殿",2),("7","婚姻与独身",1),("8–10","祭偶像之物、自由与爱、以色列的鉴戒",3),("11–14","公共敬拜：蒙头、主餐、恩赐、爱的道",4),("15","基督与信徒的身体复活",1),("16","捐项与问安",1)],
 bt="保罗把哥林多教会放在**出埃及—旷野**的大故事里：“我们的祖宗从前都在云下……都在云里、海里受洗归了摩西”（{{林前10:1-2}}），他们的倒毙“要作为鉴戒”。教会是新的圣殿（3:16），基督是我们的逾越节羔羊（5:7），主餐是“新约”之杯（11:25），复活是初熟的果子（15:20，对照利 23 章初熟节）。第 15 章以“首先的人亚当……末后的亚当”收束整个创造—新创造的故事。",
 ct="==立约群体的圣洁==：旧约“把那恶人从你们中间赶出去”（{{林前5:13}}，引申 17:7）直接用在教会纪律；“新约”的杯（11:25）使主餐成为立约的筵席，不按理吃喝的就是“干犯主的身、主的血”。==信徒的儿女“是圣洁的”==（{{林前7:14}}），被改革宗视为儿女属于圣约的根据之一（参多特 1.17）。旧约以色列与新约教会是一个立约百姓，故其鉴戒对我们有效。",
 key=["**十字架的智慧** vs 世人的智慧（1:18-2:5）","**教会是神的殿**、身体是圣灵的殿（3:16；6:19）","**自由受爱的约束**（8–10 章）","**爱是最妙的道**（13 章）","**复活的福音**：基督照圣经所说死、埋葬、复活（15:3-4）"],
 hard=[("!!蒙头（11:2-16）!!","原则：创造秩序中的“头”（11:3）与公共敬拜的端庄；形式（头巾）带有文化表达。改革宗教会多数持守原则（男女同等有神的形象，在家庭与教会中秩序不同），在具体头巾实践上有分歧。"),
  ("!!“方言”与先知恩赐今天还有吗（12–14 章）!!","多数改革宗（加尔文、HC 传统、多特宗教会议后的主流）持启示性恩赐止息观：使徒与先知是教会的根基（弗2:20），正典完成后，启示性的说预言与方言不再延续；而爱、教导、治理、帮补的恩赐持续。关键测试是 14 章“造就教会”与“规规矩矩地按着次序”（14:40）。"),
  ("!!“为死人受洗”（15:29）!!","释经难点，有数十种解释，没有一种被普遍接受；可确定的是保罗并未认可该做法，只用它作论证复活的“人身论证”（他们尚且如此，若死人不复活又何必？）。不可据此建立教义。")],
 conf=[("hc",45),("bc",29,"真教会的标志如下：她宣讲纯正的福音；她按照基督当初设立圣礼的样式施行圣礼；她为纠正错误、刑罚罪恶而执行教会纪律。"),("dort",1,17),("bc",37,"那些已经死了的人都要复活，他们的灵魂要与自己以前的身体联合；")],
 app=["用 1:18-31 检验我们追捧的“名人文化”。","在自由的事上先问：这能造就人吗（10:23）？","守主餐前省察自己，也要彼此等待（11:28,33）。","15:58：因复活，劳苦在主里不是徒然的。"],
 ang={"历史":"罗马殖民地中的多阶层教会","文学":"“论到……”逐条回应来信","神学":"十字架神学、教会论、复活论","牧养":"纪律、婚姻、敬拜秩序的实际指南"}),

dict(id="2co", n="哥林多后书", ab="林后", en="2 Corinthians", g="major", ic="🏺", ch=13,
 au="使徒保罗与提摩太（{{林后1:1}}）", date="约主后 55–56 年秋", place="马其顿（可能在腓立比，{{林后2:13}}；{{林后7:5}}）",
 to="哥林多教会及亚该亚众圣徒", fr="philippi", dest="corinth", acts="徒20:1-3",
 kw="职事", core="新约的职事在软弱中显出神的能力：瓦器里有宝贝，十字架的模式就是使徒的模式。",
 kv="林后5:17", mn="安慰·瓦器·和好·捐项·软弱（1·4·5·8–9·12 章）",
 bg="写完前书后，哥林多局势恶化：保罗曾作“忧愁的探访”（2:1），又写过“流泪的信”（2:4），由提多送去。他在特罗亚等不到提多，心里不安，渡到马其顿，终于得着教会悔改的好消息（7:6-7）。但一班自称“超级使徒”的人（11:5）又攻击保罗的外表、口才与收钱方式。本书是保罗最具个人色彩的书信。",
 cul="希腊演说文化看重仪表与口才（10:10“气貌不扬，言语粗俗”）；收学费的巡回哲士以收入证明身价，保罗却自食其力（11:7-9）。“凯旋游行”（2:14）、“瓦器”（4:7，廉价陶灯）、“推荐信”（3:1）都是当时生活意象。",
 why=["向悔改的教会表达安慰与和好（1–7）","完成耶路撒冷捐项（8–9）","驳斥假使徒，捍卫使徒职分（10–13）"],
 ol=[("1–7","使徒职事：安慰、新约的执事、瓦器、和好的职分",7),("8–9","恩典的捐项：基督的贫穷使我们富足",2),("10–13","在软弱中夸口：驳假使徒；第三重天与肉中刺",4)],
 bt="第 3 章是新约与旧约（西奈）最集中的对比：石版与心版（{{林后3:3}}，引耶 31、结 36），叫人死的字句与叫人活的精意，摩西脸上渐退的荣光与主的荣光使我们变成主的形状（3:18）。5:17“新造的人”回响以赛亚的新天新地（赛 65:17）。6:16-18 把利未记、以西结书、撒母耳记下的立约公式汇成一串，宣告教会就是神的圣殿。",
 ct="==“新约的执事”（3:6）==：这里对比的不是两种得救方法，而是同一恩典之约在两个时代的施行：旧约的施行以石版与仪文为特征，“定罪的职事”；新约的施行以圣灵写在心版为特征，“称义的职事”，荣光更大（3:9）。==立约公式“我要作他们的神，他们要作我的子民”==（6:16）在新约教会中应验。5:21 是“归算”交换的经典经文。",
 key=["**新约的职事**胜过旧约的荣光（3 章）","**瓦器里有宝贝**（4:7）","**和好的职分**与“奇妙的交换”（5:18-21）","**恩典的捐项**（8:9）","**神的能力在人的软弱上显得完全**（12:9）"],
 hard=[("!!本书是否由几封信拼成?!!","许多批判学者主张 10–13 章是“流泪的信”；但现存所有抄本都是完整的十三章，语气转折可解释为：先对悔改的多数说话，再对仍受假使徒影响的人说话。正统立场按正典现有形式解释。"),("!!5:10“必要在基督台前显露出来”与因信称义冲突吗?!!","不冲突。信徒不再被定罪，但他们的工作要被显明并按恩典受赏（参 BC 37：“按善恶受报（林后5:10）”）。行为是称义的果子与证据，不是根据。")],
 conf=[("hc",56),("bc",23,"保罗还说我们是“蒙神的恩典，因基督耶稣的救赎，就白白地称义”（罗3:24）。"),("bc",37,"然后，案卷将被展开，已死的人照着他们在世上所行的受审判（启20:12），按善恶受报（林后5:10）。")],
 app=["服事者不靠形象与口才，而靠真道与圣灵。","苦难中先学会“受安慰”，再去安慰人（1:4）。","奉献是恩典的回应，“乐意的”（9:7）。","把软弱带到主前，祂的恩典够用（12:9）。"],
 ang={"历史":"保罗与哥林多关系的“最低谷与修复”","文学":"自传式辩护，带“愚妄人的夸口”（11–12）反讽","神学":"新约论、和好论、苦难神学","牧养":"传道人的心肠与教会的捐献"}),

dict(id="gal", n="加拉太书", ab="加", en="Galatians", g="major", ic="🕊️", ch=6,
 au="使徒保罗（{{加1:1}}）", date="约主后 48–49 年（南加拉太说，耶路撒冷会议前）；另一说 53–55 年", place="叙利亚的安提阿（或以弗所/马其顿）",
 to="加拉太众教会（彼西底的安提阿、以哥念、路司得、特庇，{{徒13}}–{{徒14}}）", fr="antioch", dest="iconium", acts="徒13–15",
 kw="自由", core="人称义不是因行律法，乃是因信耶稣基督；在基督里的自由是圣灵中的新生命，不是放纵。",
 kv="加2:20", mn="1–2 自传（福音来自神）·3–4 教义（亚伯拉罕与应许）·5–6 实践（圣灵的果子）",
 bg="保罗第一次旅行在南加拉太建立教会后，一批来自犹太地的人（“奋锐的犹太派”）随后进来，教导外邦信徒必须受割礼、守节期，才算完全属于亚伯拉罕的家（{{加5:2-4}}；{{加4:10}}）。连彼得在安提阿也一度退缩，不与外邦人同桌（{{加2:11-14}}）。保罗以最激烈的语气写信：这是“别的福音”（1:6-9）。此争议最终促成耶路撒冷会议（{{徒15}}）。",
 cul="加拉太省是罗马在小亚细亚中部设的大省，北部是凯尔特人（高卢人）后裔，南部是希腊化城市与罗马殖民地（彼西底的安提阿、路司得），帝王崇拜兴盛。犹太人以割礼、饮食、安息日作为身份标记；对外邦归信者而言，受割礼意味着被犹太会堂接纳并免受“不敬神”的社会压力（6:12）。",
 why=["假教师传“别的福音”：割礼+守律法（1:6-7）","有人质疑保罗使徒权柄来源（1:1,11-12）","连彼得、巴拿巴也在饮食上随伙装假（2:13）","信徒有被“不要再被奴仆的轭挟制”的危险（5:1）"],
 ol=[("1–2","历史：保罗的福音直接来自基督；安提阿冲突；因信称义",2),("3–4","教义：亚伯拉罕之约、律法的功用、儿子的名分、两个妇人的寓意",2),("5–6","实践：基督释放了我们；顺着圣灵而行；彼此担当",2)],
 bt="加拉太书把救赎历史排序：**应许（亚伯拉罕）→ 律法（西奈，430 年后）→ 基督（应许的那一位“子孙”）→ 圣灵（应许的福）**（{{加3:14-19}}）。律法是“训蒙的师傅”，引我们到基督（3:24）；“及至时候满足”，神差祂的儿子（4:4）。“神的以色列”（6:16）指在基督里的新创造群体。",
 ct="==亚伯拉罕之约是恩典之约的核心样式==：“你们既属乎基督，就是亚伯拉罕的后裔，是照着应许承受产业的了”（{{加3:29}}）。==后来 430 年才有的律法，不能废掉神预先所立的约，叫应许归于虚空==（3:17）——这正是改革宗“律法与福音”区分的经文锚点，也说明西奈之约是恩典之约的一种施行，而非另一条得救之路。4:21-31 夏甲与撒拉的寓意：两种“约”的施行方式（为奴/自由）与两种儿女（按肉体/按应许）。",
 key=["**唯一的福音**：加添任何条件就是“别的福音”（1:6-9）","**因信称义**的经典宣告（2:16）","**与基督同钉、基督在我里面活**（2:20）","**应许先于律法**（3:15-22）","**圣灵的果子**（5:22-23）"],
 hard=[("!!南加拉太说 vs 北加拉太说!!","南说（拉姆塞、F. F. Bruce 等）：收信人是第一次旅行建立的教会，书信早于耶路撒冷会议，所以保罗不提会议决议。北说（多数德国批判学者、部分古代教父）：收信人是北部凯尔特族地区，写于第三次旅行期间。本站采南说，但两说都不影响教义。"),
  ("!!保罗反对的是“律法主义”还是“犹太身份标记”（保罗新观）?!!","新观（桑德斯、邓雅各、赖特）强调“律法的行为”主要是割礼、饮食、节期等族群标记；改革宗回应：标记问题确实存在，但保罗把它推到根源——任何人想靠行为在神面前称义都在咒诅之下（3:10-13）。称义是法庭的、基于基督代替受咒诅，这一点不能被教会论取代。")],
 conf=[("hc",61),("bc",7,"因此，任何人教导有悖于圣经的道理都是不合法的，即便是使徒，或（如使徒保罗所说）天上来的使者也不例外（参见加1:8）。"),("bc",24,"因为我们所说的不是空洞的信心，而是圣经中称为“使人生发仁爱的信心”（加5:6）。"),("bc",25,"我们相信，随着基督的降世，礼仪律及其象征已被停用；我们也相信，所有的预表都已实现。")],
 app=["警惕“耶稣 + X”的福音（任何附加条件）。","用自由去服事人，不是放纵情欲（5:13）。","在教会中实行温柔挽回（6:1）。","以十字架为唯一夸口（6:14）。"],
 ang={"历史":"最早的保罗书信之一，耶路撒冷会议的前奏","文学":"缺少感恩段，直接责备，情感最激烈","神学":"称义、律法、应许、圣灵","牧养":"自由与彼此担当"}),
]
